import re, collections

def get_stats(vocab):
    pairs = collections.defaultdict(int)
    for word, freq in vocab.items():
        symbols = word.split()
        for i in range(len(symbols) - 1):
            pairs[symbols[i], symbols[i + 1]] += freq
    return pairs

def merge_vocab(pair, v_in):
    bigram = re.escape(' '.join(pair))
    p = re.compile(r'(?<!\S)' + bigram + r'(?!\S)')
    return {p.sub(''.join(pair), w): f for w, f in v_in.items()}

vocab = {'l o w </w>': 5, 'l o w e r </w>': 2,
         'n e w e s t </w>': 6, 'w i d e s t </w>': 3}
merges = []
for i in range(10):
    pairs = get_stats(vocab)
    best = max(pairs, key=pairs.get)  # ties: first pair seen
    vocab = merge_vocab(best, vocab)
    merges.append(best)
print(merges)

def get_stats(ids, counts=None):
    counts = {} if counts is None else counts
    for pair in zip(ids, ids[1:]):
        counts[pair] = counts.get(pair, 0) + 1
    return counts

def merge(ids, pair, idx):
    out, i = [], 0
    while i < len(ids):
        if i < len(ids) - 1 and (ids[i], ids[i + 1]) == pair:
            out.append(idx); i += 2
        else:
            out.append(ids[i]); i += 1
    return out

def train(text, vocab_size):
    ids = list(text.encode("utf-8"))        # ints 0..255
    merges = {}                             # (a, b) -> new id
    vocab = {i: bytes([i]) for i in range(256)}
    for idx in range(256, vocab_size):
        stats = get_stats(ids)
        pair = max(stats, key=stats.get)    # ties: first seen
        ids = merge(ids, pair, idx)
        merges[pair] = idx
        vocab[idx] = vocab[pair[0]] + vocab[pair[1]]
    return merges, vocab

def encode(text, merges):
    ids = list(text.encode("utf-8"))
    while len(ids) >= 2:
        stats = get_stats(ids)
        pair = min(stats, key=lambda p: merges.get(p, float("inf")))
        if pair not in merges:
            break                           # no merge applies
        ids = merge(ids, pair, merges[pair])
    return ids

def decode(ids, vocab):
    raw = b"".join(vocab[i] for i in ids)
    return raw.decode("utf-8", errors="replace")

merges, vocab = train("aaabdaaabac", 256 + 3)
print(merges)  # {(97, 97): 256, (256, 97): 257, (257, 98): 258}
ids = encode("aaabdaaabac", merges)
print(ids)     # [258, 100, 258, 97, 99]
assert decode(ids, vocab) == "aaabdaaabac"
